lua local Players = game:GetService("Players") local RunService = game:GetService("RunService")  local player = Players.LocalPlayer local playerGui = player:WaitForChild("PlayerGui")  local gui = Instance.new("ScreenGui") gui.Name = "MobileAimTrainer" gui.ResetOnSpawn = false gui.Parent = playerGui  local button = Instance.new("TextButton") button.Name = "AimButton" button.Size = UDim2.fromOffset(110, 50) button.Position = UDim2.new(1, -130, 0.7, 0) button.BackgroundColor3 = Color3.fromRGB(35, 35, 35) button.TextColor3 = Color3.new(1, 1, 1) button.TextScaled = true button.Text = "AIM: OFF" button.Parent = gui  local corner = Instance.new("UICorner") corner.CornerRadius = UDim.new(0, 12) corner.Parent = button  local crosshair = Instance.new("TextLabel") crosshair.Name = "Crosshair" crosshair.Size = UDim2.fromOffset(40, 40) crosshair.AnchorPoint = Vector2.new(0.5, 0.5) crosshair.Position = UDim2.fromScale(0.5, 0.5) crosshair.BackgroundTransparency = 1 crosshair.Text = "+" crosshair.TextColor3 = Color3.fromRGB(0, 255, 100) crosshair.TextScaled = true crosshair.Visible = false crosshair.Parent = gui  local aimEnabled = false  button.Activated:Connect(function()     aimEnabled = not aimEnabled      if aimEnabled then         button.Text = "AIM: ON"         button.BackgroundColor3 = Color3.fromRGB(0, 140, 70)         crosshair.Visible = true     else         button.Text = "AIM: OFF"         button.BackgroundColor3 = Color3.fromRGB(35, 35, 35)         crosshair.Visible = false     end end)  RunService.RenderStepped:Connect(function()     if aimEnabled then         crosshair.Position = UDim2.fromScale(0.5, 0.5)     end end) 
